const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fd=s=>s?new Date(s).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const fdd=s=>s?new Date(s).toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'}):'en cours';
const F=n=>Number(n).toLocaleString('fr-FR')+' FCFA';
const NEXT_SLOT=()=>{const d=new Date();d.setMinutes(Math.floor(d.getMinutes()/15)*15+15,0,0);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)};
async function api(p,b){const o=b===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'fetch'},body:JSON.stringify(b)};const r=await fetch('/api'+p,o);const d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(d.erreur||'Erreur');e.status=r.status;throw e}return d}
function toast(t,err){const e=document.createElement('div');e.className='toast'+(err?' err':'');e.setAttribute('role',err?'alert':'status');e.setAttribute('aria-live',err?'assertive':'polite');e.textContent=t;document.body.appendChild(e);setTimeout(()=>e.remove(),3400)}
const tbl=(h,rows)=>`<table><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${h.length}" style="color:var(--mute)">Aucune donnée</td></tr>`}</table>`;
const ROLES={patient:'Patient',psychologue:'Psychologue',personnalite:'Personnalité',parent:'Parent',parrain:'Parrain',partenaire:'Partenaire',admin:'Administrateur'};
const NAV={patient:[['accueil','Accueil'],['rdv','Rendez-vous'],['appels','Historique des appels'],['ateliers','Ateliers'],['abo','Abonnement'],['comm','Communauté'],['partners','Partenaires']],
psychologue:[['patients','Mes patients'],['rdv','Rendez-vous et créneaux'],['appels','Historique des appels'],['ateliers','Ateliers et groupes'],['prog','Programmes spéciaux'],['comm','Communauté'],['partners','Partenaires']],
personnalite:[['prog','Programmes spéciaux'],['partners','Partenaires']],
parent:[['suivi','Suivi de mon enfant'],['rdv','Rendez-vous'],['abo','Abonnement'],['partners','Partenaires']],
parrain:[['suivi','Suivi'],['abo','Soutien financier'],['partners','Partenaires']],
partenaire:[['suivi','Bénéficiaires'],['abo','Soutien financier'],['partners','Partenaires']],
admin:[['stats','Tableau de bord'],['users','Utilisateurs'],['aff','Affectations'],['prog','Programmes spéciaux'],['comm','Communautés'],['partners','Partenaires'],['tarifs','Tarifs'],['audit','Journal d’audit']]};
let me=null,page='',commOpen=null,formule='premium',partnerFilter='all';
/* ---------- connexion ---------- */
async function loginView(){let partners=[];try{partners=await api('/partenaires')}catch(e){}
const plist=(partners||[]).slice(0,8).map(p=>`<span class="login-partner-item">${p.logo_url?`<img src="${esc(p.logo_url)}" alt="${esc(p.nom)}" referrerpolicy="no-referrer">`:''}<span>${esc(p.nom)}</span></span>`).join('');
$('#app').innerHTML=`<div class="login">
  <div class="hero">
    <div class="lg"><img src="/logo-connexion.jpeg" alt="Mens Sana — De l'enfermement intérieur à la liberté d'être"></div>
    <h1>Prendre soin de l'esprit des jeunes, avec leurs proches.</h1>
    <p>Suivi psychologique, ateliers et accompagnement des jeunes au Sénégal, avec un espace dédié aux parents, parrains et partenaires.</p>
    <div class="pills"><span>Consentement et confidentialité</span><span>Journal d'audit</span><span>Rôles et accès contrôlés</span></div>
    <div class="login-partners"><div class="partners-title">NOS PARTENAIRES</div><div class="login-partner-list">${plist||'<span class="login-partner-item"><span>Partenaires à venir</span></span>'}</div></div>
  </div>
  <div class="lbox"><div class="login-form-wrap">
    <h2>Connexion</h2>
    <p class="sub">Accédez à votre espace Mens Sana.</p>
    <form data-f="login">
      <label for="login-email">Adresse e-mail</label>
      <input id="login-email" name="email" type="email" required autocomplete="username">
      <label for="login-password">Mot de passe</label>
      <input id="login-password" name="password" type="password" required autocomplete="current-password">
      <button class="btn login-submit" type="submit">Se connecter</button>
    </form>
    <p class="login-links">Patient, parent ou parrain ? <a href="#" data-a="showSignup"><strong>Créer un compte</strong></a> · <a href="#" data-a="showPartners">Nos partenaires</a></p>
    <p class="login-note">Psychologues, personnalités et partenaires : votre compte est créé par l'administration, utilisez les identifiants reçus.</p>
  </div></div>
</div>`}
function inscriptionView(){$('#app').innerHTML=`<div class="public-page"><header><img src="/mark.webp" alt=""><b>Mens Sana</b><button class="btn-secondaire btn-petit" data-a="backLogin">Retour à la connexion</button></header><main><h1>Créer mon compte</h1><p class="sub">Les comptes patient, parent/tuteur et parrain peuvent être créés ici. Les psychologues, personnalités et partenaires sont ajoutés par l’administrateur.</p><form class="card public-form form-grid" data-f="signup"><label>Je suis</label><select name="role" required><option value="patient">Patient</option><option value="parent">Parent ou tuteur (d’un mineur)</option><option value="parrain">Parrain (d’un mineur)</option></select><label>Nom complet</label><input name="nom" maxlength="120" required><label>E-mail</label><input name="email" type="email" autocomplete="email" required><div data-signup-fields="patient"><label>Date de naissance</label><input name="date_naissance" type="date" max="${new Date().toISOString().slice(0,10)}" required></div><label>Mot de passe (10 caractères minimum)</label><input name="password" type="password" minlength="10" autocomplete="new-password" required><div class="full" style="margin-top:18px"><button class="btn" type="submit">Créer mon compte</button></div></form></main></div>`}
/* ---------- structure ---------- */
function shell(){const n=[...NAV[me.role]||[], ...(me.role==='admin'?[['conf','Sécurité & limites']]:[])];
$('#app').innerHTML=`<div class="shell"><aside class="side"><div class="brand"><img src="/mark.webp" alt="">Mens Sana</div>${n.map(x=>`<button data-a="go" data-p="${x[0]}" class="${x[0]===page?'on':''}">${x[1]}</button>`).join('')}<div class="who"><b>${esc(me.nom)}</b>${ROLES[me.role]}<br><button data-a="logout" class="logout-link">Se déconnecter</button></div></aside><main class="main" id="main"></main></div>`}
async function show(){shell();const m=$('#main');m.innerHTML='<p class="sub">Chargement…</p>';try{m.innerHTML=await (PAGES[page]||PAGES.conf)()}catch(e){m.innerHTML=`<div class="note">${esc(e.message)}</div>`}}
async function publicPartners(){const P=await api('/partenaires');const types={ong:'ONG',ecole:'École',organisation:'Organisation',institution:'Institution'};const visible=partnerFilter==='all'?P:P.filter(p=>p.type===partnerFilter);$('#app').innerHTML=`<div class="public-page"><header><img src="/mark.webp" alt=""><b>Mens Sana</b><button class="btn-secondaire btn-petit" data-a="backLogin">Retour à la connexion</button></header><main><h1>Nos partenaires</h1><p class="sub">Les organisations qui contribuent à faciliter l’accès à l’accompagnement.</p><nav class="partner-filters" aria-label="Filtrer les partenaires">${[['all','Tous'],...Object.entries(types)].map(([key,label])=>`<button class="filter-chip ${partnerFilter===key?'active':''}" aria-pressed="${partnerFilter===key}" data-a="filterPartner" data-type="${key}">${label}</button>`).join('')}</nav><div class="grid partner-grid">${visible.map(p=>`<article class="card partner-card"><div class="partner-logo-wrap"><img class="partner-logo" src="${esc(p.logo_url)}" alt="Logo ${esc(p.nom)}" referrerpolicy="no-referrer"></div><span class="tag">${types[p.type]||esc(p.type)}</span><h2>${esc(p.nom)}</h2><p>${esc(p.description)}</p>${p.site_url?`<a href="${esc(p.site_url)}" target="_blank" rel="noopener noreferrer">Visiter le site</a>`:''}</article>`).join('')||'<p class="note">Les partenaires seront publiés ici.</p>'}</div></main></div>`}
async function boot(){try{me=await api('/me');page=NAV[me.role][0][0];show()}catch(e){if(e.status===401){await loginView();}else $('#app').textContent='Impossible de charger votre session. Rechargez la page ou reconnectez-vous.'}}
/* ---------- fiches ---------- */
function fiche(p){const e=(p.evaluations||[])[0],a=p.abonnement;return `<div class="stack"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><h2>${esc(p.nom)}</h2><span class="tag">${esc(p.numero)}</span> <span class="tag">${p.age} ans${p.mineur?' · mineur':''}</span></div><button class="btn-secondaire btn-petit" data-a="close">Fermer</button></div>
<div class="grid"><div class="card"><div class="k">Psychologue</div>${p.psy?`<b>${esc(p.psy.nom)}</b><br>${esc(p.psy.specialite)} · ${p.psy.annees_exp} ans d’expérience`:'Non affecté'}</div><div class="card"><div class="k">État (médecin)</div>${e?`<b>${esc(e.etat)}</b><br>Programme : ${esc(e.programme||'aucun')}`:'Pas encore évalué'}</div><div class="card"><div class="k">Abonnement</div>${a?`<b>${esc(a.label)}</b> jusqu’au ${fdd(a.fin)}`:'Aucun'}</div></div>
${p.famille!=null?`<div class="card"><div class="k">Informations familiales</div>${esc(p.famille)}</div>`:''}
<div class="card"><div class="k">Rendez-vous</div>${tbl(['Date','Mode','Psychologue','Statut'],p.rdv.map(r=>[fd(r.date_heure),r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),esc(r.psy),`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`]))}</div>
<div class="grid"><div class="card"><div class="k">Ateliers et groupes</div>${[...p.ateliers.map(x=>esc(x.titre)+' · '+fd(x.date_heure)),...p.groupes.map(x=>'Groupe : '+esc(x.nom))].join('<br>')||'Aucun'}</div><div class="card"><div class="k">Évolution</div>${p.evaluations.map(x=>`${fdd(x.date)} · ${esc(x.etat)}`).join('<br>')||'Aucune évaluation'}</div></div>
<div class="card"><div class="k">Historique des psychologues</div>${tbl(['Psychologue','Début','Fin','Motif'],p.historique.map(h=>[esc(h.psy),fdd(h.debut),fdd(h.fin),esc(h.motif||'')]))}</div>
${p.evaluations_psy?`<div class="card"><div class="k">Évaluations psychologiques de séance</div>${p.evaluations_psy.map(s=>`<p><b>${fd(s.date_heure)}</b> · ${esc(s.observation)}</p>`).join('')||'Aucune évaluation'}</div>`:''}
${p.seances?`<div class="card"><div class="k">Notes de séance confidentielles</div>${p.seances.map(s=>`<p><b>${fd(s.date_heure)}</b> · ${esc(s.resume)}</p>`).join('')||'Aucune note'}</div>`:''}</div>`}
const openModal=h=>{$('#modal').innerHTML='<div role="dialog" aria-modal="true">'+h+'</div>';$('#modal').classList.add('on')};
async function openFiche(id){openModal(fiche(await api('/patients/'+id)))}
function receiptHtml(r){return `<article id="receipt" class="receipt"><img src="/logo.webp" alt="Mens Sana"><h2>Reçu de paiement</h2><p class="receipt-ref">Référence ${esc(r.reference)}</p><dl><dt>Date</dt><dd>${esc(r.date)}</dd><dt>Bénéficiaire</dt><dd>${esc(r.patient)} · ${esc(r.numero)}</dd><dt>Payeur</dt><dd>${esc(r.payeur)}</dd><dt>Formule</dt><dd>${esc(r.formule)}</dd><dt>Moyen</dt><dd>${esc(r.methode)}</dd><dt>Montant</dt><dd>${F(r.montant)}</dd></dl><p class="receipt-test">Paiement enregistré en mode test</p><button class="btn" data-a="printReceipt">Imprimer le reçu</button> <button class="btn-secondaire" data-a="close">Fermer</button></article>`}
/* ---------- pages ---------- */
const slotOptions=C=>C.map(s=>`<option value="${s.id}">${fd(s.date_heure)} · ${s.duree} min</option>`).join('')||'<option value="">Aucun créneau disponible</option>';
const rdvTable=(R,psy,canCancel=false)=>tbl(psy?['Date','Patient','Mode','Statut','']:['Date','Psychologue','Mode','Lieu','Statut',''],R.map(r=>psy?[fd(r.date_heure),esc(r.patient)+' <small>'+esc(r.numero)+'</small>',r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`,r.statut==='prévu'?`<button class="btn-secondaire btn-petit" data-a="seance" data-id="${r.id}" data-mode="${esc(r.mode)}">${r.mode==='appel'?'Enregistrer l’appel':'Clôturer'}</button>`:'']:[fd(r.date_heure),esc(r.psy),r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),r.mode==='centre'?esc(r.lieu):'À distance',`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`,canCancel&&r.statut==='prévu'?`<button class="btn-danger btn-petit" data-a="cancelRdv" data-id="${r.id}">Annuler</button>`:'']));
const PAGES={
async appels(){const A=await api('/appels'),clinician=me.role==='psychologue';return `<h2>Historique des appels</h2><p class="sub">Appels vocaux et visioconférences réalisés à distance.</p>${clinician?'<p class="note">Les rapports brefs sont accessibles uniquement aux psychologues concernés.</p>':''}<div class="card">${tbl(clinician?['Date','Patient','Professionnel','Type','Durée','État','Rapport bref']:['Date','Professionnel','Type','Durée','État'],A.map(a=>clinician?[fd(a.date_heure),esc(a.patient)+' · '+esc(a.numero),esc(a.psychologue),(a.mode_appel==='video'||a.mode==='appel_video')?'Vidéo':'Vocal',a.duree_min+' min',esc(a.statut),esc(a.rapport_bref||'—')]:[fd(a.date_heure),esc(a.psychologue),(a.mode_appel==='video'||a.mode==='appel_video')?'Vidéo':'Vocal',a.duree_min+' min',esc(a.statut)]))}</div>`},
async accueil(){const d=await api('/patient/home'),P=await api('/psychologues'),e=(d.evaluations||[])[0],a=d.abonnement,n=(d.rdv||[]).filter(r=>r.statut==='prévu').reverse()[0];
const aboMsg=d.abonnement_message?`<div class="note" style="margin:12px 0">${esc(d.abonnement_message)}</div>`:'';const gate=!d.seance_realisee?`<div class="note" style="margin:12px 0">Accès aux ateliers : effectuez d’abord au moins une séance avec un psychologue afin d’établir votre fiche patient.</div>`:'';
return `<h2>Bonjour ${esc((d.nom||'').split(' ')[0])}</h2><p class="sub">Votre numéro de patient : <span class="tag">${esc(d.numero||'')}</span></p>${aboMsg}${gate}<div class="grid"><div class="card"><div class="k">Mon psychologue</div>${d.psy?`<div class="big" style="font-size:22px">${esc(d.psy.nom)}</div>${esc(d.psy.specialite||'')}<br>${d.psy.annees_exp||0} ans d’expérience`:'Aucun psychologue affecté'}</div><div class="card"><div class="k">Prochain rendez-vous</div>${n?`<div class="big" style="font-size:22px">${fd(n.date_heure)}</div>${n.mode==='centre'?'Au centre Mens Sana':(n.mode==='appel_video'?'Visioconférence':'Appel vocal')}<br>${esc(n.lieu||'')}`:'Aucun rendez-vous prévu'}</div><div class="card"><div class="k">Abonnement</div>${a?`<div class="big" style="font-size:22px">${esc(a.label)}</div>Jusqu’au ${fdd(a.fin)}`:(d.abonnement_message?`<span class="tag w">Inactif</span><br>${esc(d.abonnement_message)}`:'Aucun abonnement actif')}</div><div class="card"><div class="k">Fiche patient</div>${d.seance_realisee?'<span class="tag o">Établie</span><br>Première séance réalisée avec un psychologue.':'<span class="tag w">À établir</span><br>Réalisez une première séance avec un psychologue.'}</div></div>
<div class="card" style="margin-top:16px"><h3>Changer de psychologue</h3><p class="sub">Selon votre avancement, vous pouvez en changer. L’historique est conservé.</p><form data-f="changer" class="form-grid"><div><label>Nouveau psychologue</label><select name="psy_id">${P.map(p=>`<option value="${p.id}">${esc(p.nom)} · ${esc(p.specialite)}</option>`).join('')}</select></div><div><label>Motif</label><input name="motif" placeholder="Ex. nouveau stade d’avancement"></div><div><button class="btn" type="submit">Changer</button></div></form></div>
<div class="card" style="margin-top:16px"><div class="k">Historique de mes psychologues</div>${tbl(['Psychologue','Début','Fin','Motif'],(d.historique||[]).map(h=>[esc(h.psy),fdd(h.debut),fdd(h.fin),esc(h.motif||'')]))}</div>`},
async rdv(){if(me.role==='psychologue'){const [d,C]=await Promise.all([api('/psy/home'),api('/psy/creneaux')]);const callBtn=r=>r.statut==='prévu'&&(r.mode==='appel_audio'||r.mode==='appel_video'||r.mode==='appel')?`<span class="call-actions"><button class="btn btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_video" data-with="${esc(r.patient||'Patient')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/></svg> Appel vidéo</button><button class="btn-secondaire btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_audio" data-with="${esc(r.patient||'Patient')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.63 2.63a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.45-1.2a2 2 0 0 1 2.11-.45c.85.3 1.73.51 2.63.63A2 2 0 0 1 22 16.92z"/></svg> Appel vocal</button></span>`:'';const rows=(d.rdv||[]).map(r=>[fd(r.date_heure),esc(r.patient)+' <small>'+esc(r.numero||'')+'</small>',r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`,(r.statut==='prévu'?`<button class="btn-secondaire btn-petit" data-a="seance" data-id="${r.id}" data-mode="${esc(r.mode)}">${r.mode==='centre'?'Clôturer':'Enregistrer l’appel'}</button> `:'')+callBtn(r)]);return `<h2>Rendez-vous et créneaux</h2><p class="sub">Proposez des horaires, gérez les rendez-vous et lancez les appels vocaux/vidéo à distance.</p><div class="card"><form data-f="slot" class="form-grid"><div><label>Nouvelle disponibilité</label><input type="datetime-local" name="date_heure" min="${NEXT_SLOT()}" step="900" required></div><div><button class="btn" type="submit">Ajouter le créneau</button></div></form></div><div class="card" style="margin-top:16px"><h3>Mes disponibilités</h3>${tbl(['Date','Durée','État',''],C.map(s=>[fd(s.date_heure),s.duree+' min',s.patient?`Réservé par ${esc(s.patient)}`:s.actif?'Disponible':'Retiré',s.actif&&!s.patient?`<button class="btn-danger btn-petit" data-a="cancelSlot" data-id="${s.id}">Retirer</button>`:'']))}</div><div class="card" style="margin-top:16px"><h3>Rendez-vous</h3>${tbl(['Date','Patient','Mode','Statut','Actions'],rows)}</div>`}
let beneficiaires=[],patientId,canCancel=false;
if(me.role==='parent'){beneficiaires=await api('/suivi');patientId=beneficiaires.length?beneficiaires[0].id:null;canCancel=true}
else{const d=await api('/patient/home');beneficiaires=[d];patientId=d.id;canCancel=true}
const C=patientId?await api(`/creneaux/${patientId}`):[], R=beneficiaires.length?(beneficiaires[0].rdv||[]):[];
const callBtn=r=>r.statut==='prévu'&&(r.mode==='appel_audio'||r.mode==='appel_video'||r.mode==='appel')?`<span class="call-actions"><button class="btn btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_video" data-with="${esc(r.psy||'Psychologue')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/></svg> Appel vidéo</button><button class="btn-secondaire btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_audio" data-with="${esc(r.psy||'Psychologue')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.63 2.63a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.45-1.2a2 2 0 0 1 2.11-.45c.85.3 1.73.51 2.63.63A2 2 0 0 1 22 16.92z"/></svg> Appel vocal</button></span>`:'';
const rdvRows=R.map(r=>[fd(r.date_heure),esc(r.psy||''),r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),esc(r.lieu||''),`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`,(canCancel&&r.statut==='prévu'?`<button class="btn-danger btn-petit" data-a="cancelRdv" data-id="${r.id}">Annuler</button> `:'')+callBtn(r)]);
return `<h2>Rendez-vous</h2><p class="sub">Réservez un créneau proposé par votre psychologue. Les consultations à distance sont disponibles en appel vocal ou en visioconférence.</p><div class="card">${beneficiaires.length?`<form data-f="rdv" class="form-grid">${me.role==='parent'?`<div><label>Enfant</label><select name="patient_id">${beneficiaires.map(p=>`<option value="${p.id}">${esc(p.nom)} (${esc(p.numero)})</option>`).join('')}</select></div>`:''}<div><label>Créneau disponible</label><select name="slot_id" required>${slotOptions(C)}</select></div><div><label>Mode</label><select name="mode"><option value="centre">Au centre Mens Sana</option><option value="appel_audio">Appel vocal</option><option value="appel_video">Appel vidéo</option></select></div><div><button class="btn" type="submit" ${C.length?'':'disabled'}>Réserver</button></div></form>`:'<p class="note">Aucun bénéficiaire mineur lié à votre compte pour la prise de rendez-vous.</p>'}</div><div class="card" id="rdv-list" style="margin-top:16px"><h3>Mes rendez-vous</h3>${tbl(['Date','Psychologue','Mode','Lieu','Statut','Actions'],rdvRows)}</div>`},
async ateliers(){let gate='';if(me.role==='patient'){try{const d=await api('/patient/home');if(!d.seance_realisee)gate='<div class="note" style="margin-bottom:16px">Vous devez effectuer au moins une séance avec un psychologue avant d’accéder aux ateliers. Cette première séance permet d’établir votre fiche patient.</div>';}catch(e){}}const A=await api('/ateliers');return `<h2>Ateliers et groupes</h2><p class="sub">Individuels ou en groupe. L’inscription demande une formule Premium ou Famille et une première séance réalisée avec un psychologue.</p>${gate}<div class="grid">${A.map(a=>`<div class="card"><span class="tag ${a.type==='groupe'?'':'w'}">${a.type==='groupe'?'Groupe':'Individuel'}</span><h3 style="margin:8px 0">${esc(a.titre)}</h3><p style="margin:0 0 8px;color:var(--mute)">${esc(a.description||'')}</p>${fd(a.date_heure)} · ${esc((a.lieu||'').split(',')[0])}<br>Animé par ${(a.animateurs||[]).map(esc).join(', ')}${(a.groupes||[]).length?'<br>Groupe : '+a.groupes.map(esc).join(', '):''}<br><small>${a.inscrits}/${a.capacite} places</small>${me.role==='patient'?`<br><br>${a.inscrit?'<span class="tag o">Inscrit</span>':(gate?'':'<button class="btn btn-petit" data-a="inscrire" data-id="${a.id}">S’inscrire</button>')}`:''}</div>`).join('')||'<p>Aucun atelier à venir.</p>'}</div>`},
async abo(){const [f,pay]=await Promise.all([api('/formules'),api('/paiements')]);let B=[];let meHome=null;if(me.role!=='patient'){B=await api('/suivi')}else{try{meHome=await api('/patient/home')}catch(e){}}
const logos={'Wave':'/payment-wave.svg','Orange Money':'/payment-orange.svg','Free Money':'/payment-free.svg','Carte bancaire':'/payment-card.svg'};
const aboMsg=(meHome&&meHome.abonnement_message)?`<div class="note" style="margin-bottom:16px">${esc(meHome.abonnement_message)}</div>`:'';
const tarif=f.tarif_seance||15000;const canBuy=['patient','parent','parrain'].includes(me.role);
const unit=`<div class="card" style="margin-top:16px"><h3>Séance à l’unité</h3><p class="sub">Prix d’une séance : <b>${F(tarif)}</b> / heure. Choisissez le nombre d’heures (généralement 1 h) pour comparer avec les abonnements.</p><form data-f="seance_unitaire" class="form-grid">${me.role!=='patient'?`<div><label>Bénéficiaire</label><select name="patient_id" required>${B.map(p=>`<option value="${p.id}">${esc(p.nom)} (${esc(p.numero)})</option>`).join('')}</select></div>`:''}<div><label>Nombre d’heures</label><input type="number" name="heures" min="1" max="20" value="1" required></div><div><label>Montant estimé</label><div class="tag" data-unit-total>${F(tarif)}</div></div><fieldset class="payment-methods" style="flex-basis:100%"><legend>Moyen de paiement</legend>${f.methodes.map((m,i)=>`<label class="pay-method"><input type="radio" name="methode" value="${esc(m)}" ${i===0?'checked':''} required><img src="${logos[m]||''}" alt=""><span>${esc(m)}</span></label>`).join('')}</fieldset><div class="full"><button class="btn" type="submit">Payer la séance à l’unité</button></div></form></div>`;
return `<h2>${me.role==='patient'||me.role==='parent'?'Abonnement & tarifs':'Soutien financier'}</h2><p class="sub">Abonnements mensuels et prix d’une séance à l’unité pour patient, parent/tuteur et parrain.</p>${aboMsg}<div class="grid">${Object.entries(f.formules).map(([k,v])=>`<div class="card opt ${k===formule?'on':''}" data-a="pick" data-k="${k}"><div class="k">${esc(v.label)}</div><div class="price">${F(v.prix)}<small style="font:400 13px system-ui"> /mois</small></div><ul class="c">${(v.inclus||[]).map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div>`).join('')}</div>
<div class="card payment-card" style="margin-top:16px"><h3>Abonnement mensuel</h3><form data-f="abo" class="form-grid">${me.role!=='patient'?`<label>Bénéficiaire</label><select name="patient_id" required>${B.map(p=>`<option value="${p.id}">${esc(p.nom)} (${esc(p.numero)})</option>`).join('')}</select>`:''}<fieldset class="payment-methods"><legend>Moyen de paiement</legend>${f.methodes.map((m,i)=>`<label class="pay-method"><input type="radio" name="methode" value="${esc(m)}" ${i===0?'checked':''} required><img src="${logos[m]||''}" alt=""><span>${esc(m)}</span></label>`).join('')}</fieldset><div class="full"><button class="btn" type="submit">Valider / réactiver ${esc(f.formules[formule].label)}</button></div></form></div>
${canBuy?unit:''}
<div class="card" style="margin-top:16px"><div class="k">Historique des paiements</div>${tbl(['Date','Patient','Formule / prestation','Montant','Moyen','Payeur','Statut'],(pay||[]).map(p=>[fd(p.date),esc(p.numero||''),esc(p.formule||''),F(p.montant||0),esc(p.methode||''),esc(p.payeur||''),esc(p.statut||'')]))}</div>`},
async comm(){const C=await api('/communautes'),canCreate=['admin','psychologue'].includes(me.role);let feed='';if(commOpen){try{const P=await api('/communautes/'+commOpen+'/posts');feed=`<div class="card" style="margin-top:16px"><form data-f="post" class="form-grid"><div class="full"><input name="contenu" placeholder="Écrire un message bienveillant…" maxlength="1000" required></div><div><button class="btn" type="submit">Publier</button></div></form>${P.map(p=>`<div class="post"><b>${esc(p.auteur)}</b> <small>${fd(p.date)}</small><br>${esc(p.contenu)}</div>`).join('')}</div>`}catch(e){feed=`<div class="note" style="margin-top:16px">${esc(e.message)}</div>`}}
return `<h2>Communautés</h2><p class="sub">Échangez dans des espaces bienveillants. Respectez les autres : aucun conseil médical entre membres.</p>${canCreate?`<div class="card community-create"><h3>Créer une communauté</h3><form data-f="community" class="form-grid"><div><label>Nom</label><input name="nom" maxlength="100" required></div><div><label>Description</label><input name="description" maxlength="500" required></div><div><button class="btn" type="submit">Créer</button></div></form></div>`:''}<div class="grid community-grid">${C.map(c=>`<article class="card community-card"><h3>${esc(c.nom)}</h3><p>${esc(c.description)}</p><small>${c.membres} membres</small><div class="community-actions">${c.membre?`<button class="btn-secondaire btn-petit" data-a="open" data-id="${c.id}">Ouvrir</button>`:`<button class="btn btn-petit" data-a="join" data-id="${c.id}">Rejoindre</button>`}${c.peut_gerer?`<button class="btn-danger btn-petit" data-a="deleteCommunity" data-id="${c.id}">Supprimer</button>`:''}</div></article>`).join('')||'<p class="note">Aucune communauté disponible.</p>'}</div>${feed}`},
async partners(){const types={ong:'ONG',ecole:'École',organisation:'Organisation',institution:'Institution'};
if(me.role!=='admin'){const P=await api('/partenaires');return `<h2>Partenaires</h2><p class="sub">Les organisations et partenaires de Mens Sana.</p><div class="grid partner-grid">${P.map(p=>`<article class="card partner-card"><div class="partner-logo-wrap"><img class="partner-logo" src="${esc(p.logo_url)}" alt="Logo ${esc(p.nom)}" referrerpolicy="no-referrer"></div><span class="tag">${types[p.type]||esc(p.type)}</span><h3>${esc(p.nom)}</h3><p>${esc(p.description)}</p>${p.site_url?`<a href="${esc(p.site_url)}" target="_blank" rel="noopener noreferrer">Visiter le site</a>`:''}</article>`).join('')||'<p class="note">Aucun partenaire publié pour le moment.</p>'}</div>`}
const P=await api('/admin/partenaires');const form=(p={})=>`<form data-f="partner" ${p.id?`data-id="${p.id}"`:''} class="partner-edit form-grid"><label>Nom</label><input name="nom" maxlength="120" value="${esc(p.nom||'')}" required><label>Type</label><select name="type" required>${Object.entries(types).map(([v,n])=>`<option value="${v}" ${p.type===v?'selected':''}>${n}</option>`).join('')}</select><label>Description</label><textarea name="description" maxlength="500" required>${esc(p.description||'')}</textarea><label>Adresse HTTPS du logo</label><input name="logo_url" type="url" value="${esc(p.logo_url||'')}" placeholder="https://…" required><label>Site web (facultatif)</label><input name="site_url" type="url" value="${esc(p.site_url||'')}" placeholder="https://…"><div class="partner-actions"><button class="btn">${p.id?'Enregistrer les modifications':'Ajouter le partenaire'}</button>${p.id?`<button type="button" class="btn-danger" data-a="removePartner" data-id="${p.id}">Retirer</button>`:''}</div></form>`;
return `<h2>Partenaires</h2><p class="sub">Gérez les organisations et les logos affichés sur la page publique et dans les espaces.</p><div class="card"><h3>Ajouter un partenaire</h3>${form()}</div><div class="grid partner-admin-grid">${P.map(p=>`<article class="card partner-admin-card"><div class="partner-logo-wrap"><img class="partner-logo" src="${esc(p.logo_url)}" alt="Logo ${esc(p.nom)}" referrerpolicy="no-referrer"></div><span class="tag">${types[p.type]||esc(p.type)}</span><h3>${esc(p.nom)}</h3>${form(p)}</article>`).join('')||'<p class="note">Aucun partenaire publié pour le moment.</p>'}</div>`},
async patients(){const d=await api('/psy/home');return `<h2>Mes patients</h2><p class="sub">${d.patients.length} patients suivis actuellement. La fiche patient est établie après la première séance réalisée.</p><div class="card">${tbl(['N°','Patient','Âge','État','Prochain rendez-vous',''],d.patients.map(p=>[esc(p.numero),esc(p.nom),p.age,esc(p.etat||'—'),fd(p.prochain),`<button class="btn-secondaire btn-petit" data-a="fiche" data-id="${p.id}">Ouvrir la fiche</button>`]))}</div>`},
async prog(){if(me.role==='admin'){const [G,Pers]=await Promise.all([api('/admin/programmes'),api('/personnalites')]);const cards=G.map(g=>`<div class="card"><h3>${esc(g.nom)}</h3><p style="color:var(--mute)">${esc(g.description||'')}</p><div class="k">Personnalités</div>${(g.personnalites||[]).map(p=>`<span class="tag">${esc(p.nom)}</span>`).join(' ')||'<span class="sub">Aucune</span>'}<form data-f="progLink" data-id="${g.id}" class="form-grid" style="margin-top:10px"><div><select name="personnalite_id">${Pers.map(p=>`<option value="${p.id}">${esc(p.nom)} ${p.categorie?'· '+esc(p.categorie):''}</option>`).join('')||'<option value="">Aucune personnalité</option>'}</select></div><div><button class="btn-secondaire btn-petit" type="submit" ${Pers.length?'':'disabled'}>Associer</button></div></form><div class="k" style="margin-top:12px">Activités & ateliers</div>${(g.activites||[]).map(a=>`<div class="post"><b>${esc(a.titre)}</b> <small>${esc(a.type||'')}</small><br>${esc(a.description||'')}${a.date_heure?'<br><small>'+fd(a.date_heure)+'</small>':''}</div>`).join('')||'<p class="sub">Aucune activité.</p>'}<form data-f="progActivite" data-id="${g.id}" class="form-grid" style="margin-top:10px"><div><label>Titre</label><input name="titre" required></div><div><label>Type</label><select name="type"><option value="atelier">Atelier</option><option value="activite">Activité</option></select></div><div style="flex-basis:100%"><label>Description</label><input name="description"></div><div><label>Date/heure (optionnel)</label><input type="datetime-local" name="date_heure"></div><div><button class="btn-secondaire btn-petit" type="submit">Ajouter</button></div></form></div>`).join('');return `<h2>Programmes spéciaux</h2><p class="sub">Programmes liés aux personnalités, avec ateliers et activités associés.</p><div class="card"><h3>Créer un programme spécial</h3><form data-f="progCreate" class="form-grid"><div><label>Nom</label><input name="nom" required></div><div><label>Personnalité (optionnel)</label><select name="personnalite_id"><option value="">—</option>${Pers.map(p=>`<option value="${p.id}">${esc(p.nom)}</option>`).join('')}</select></div><div style="flex-basis:100%"><label>Description</label><input name="description"></div><div><button class="btn" type="submit">Créer</button></div></form></div><div class="grid" style="margin-top:16px">${cards||'<p class="note">Aucun programme spécial.</p>'}</div>`}
const G=await api('/programmes');return `<h2>Programmes spéciaux</h2><p class="sub">Programmes et activités portés par des personnalités (influenceurs, artistes, sportifs, etc.).</p><div class="grid">${G.map(g=>`<div class="card"><h3>${esc(g.nom)}</h3><p style="color:var(--mute)">${esc(g.description||'')}</p><div class="k">Personnalités</div>${(g.personnalites||[]).map(p=>`<span class="tag">${esc(p.nom||p)}${p.categorie?' · '+esc(p.categorie):''}</span>`).join(' ')||'—'}<div class="k" style="margin-top:10px">Supervision psychologues</div>${(g.psychologues||[]).map(esc).join(', ')||'—'}<div class="k" style="margin-top:10px">Activités & ateliers</div>${(g.activites||[]).map(a=>`<div class="post"><b>${esc(a.titre)}</b> <small>${esc(a.type||'')}</small><br>${esc(a.description||'')}</div>`).join('')||'<p class="sub">Aucune activité.</p>'}</div>`).join('')||'<p class="note">Aucun programme spécial disponible.</p>'}</div>`},
async suivi(){const S=await api('/suivi'),financial=['parrain','partenaire'].includes(me.role);const cards=financial?S.map(p=>`<article class="card support-card"><div class="k">${esc(p.numero||'')}</div><h3>${esc(p.nom||'')}</h3><p>${p.abonnement?`Abonnement ${esc(p.abonnement.label)} · actif jusqu’au ${fdd(p.abonnement.fin)}`:`<span class="tag w">Abonnement inactif</span> ${esc(p.abonnement_message||'Votre abonnement n\'est plus actif, veuillez le réactiver.')}`}</p><p class="sub">Rôle : soutien financier et suivi des bénéficiaires mineurs (accès limité).</p></article>`).join(''):S.map(p=>`<div class="card">${fiche(p).replace('<button class="btn-secondaire btn-petit" data-a="close">Fermer</button>','')}</div>`).join('');return `<h2>${financial?'Bénéficiaires & soutien':'Suivi de mon enfant'}</h2><p class="sub">${financial?'Soutien financier et suivi limité des bénéficiaires mineurs.':'Évolution et activités de vos enfants mineurs.'}</p><div class="stack">${cards||'<div class="note">Aucune personne à suivre pour le moment.</div>'}</div>`},
async stats(){const s=await api('/admin/stats');return `<h2>Tableau de bord</h2><p class="sub">Vue d’ensemble de la plateforme. L’administrateur gère les comptes mais n’accède pas aux dossiers cliniques.</p><div class="grid">${[['Patients',s.patients],['Psychologues',s.psychologues],['Rendez-vous à venir',s.rdv_a_venir],['Abonnements actifs',s.abonnements],['Ateliers à venir',s.ateliers],['Revenus enregistrés',F(s.revenus)]].map(x=>`<div class="card"><div class="k">${x[0]}</div><div class="big">${x[1]}</div></div>`).join('')}</div>`},
async users(){const [U,P,L]=await Promise.all([api('/admin/users'),api('/admin/patients'),api('/admin/liens')]);const proches=U.filter(u=>['parent','parrain'].includes(u.role)).sort((a,b)=>['parent','parrain'].indexOf(a.role)-['parent','parrain'].indexOf(b.role));
return `<h2>Utilisateurs</h2><p class="sub">L’administrateur ajoute et gère les personnalités, les psychologues et les partenaires. Ils ne créent pas leur compte eux-mêmes, mais disposent de leur espace après connexion.</p>
<div class="card"><h3>Créer un compte</h3><form data-f="newuser" class="form-grid"><div><label for="nu-nom">Nom</label><input id="nu-nom" name="nom" required></div><div><label for="nu-email">E-mail</label><input id="nu-email" name="email" type="email" required></div><div><label for="newuser-role">Rôle</label><select name="role" id="newuser-role"><option value="psychologue">Psychologue</option><option value="personnalite">Personnalité</option><option value="partenaire">Partenaire</option><option value="patient">Patient</option><option value="parent">Parent / Tuteur</option><option value="parrain">Parrain</option></select></div><div data-role-extra="patient"><label for="nu-dn">Date de naissance</label><input id="nu-dn" name="date_naissance" type="date" max="${new Date().toISOString().slice(0,10)}"><span class="help">Patient concerné</span></div><div data-role-extra="psychologue" hidden><label for="nu-spec">Spécialité</label><input id="nu-spec" name="specialite" maxlength="100"><label for="nu-exp">Années d’expérience</label><input id="nu-exp" name="annees_exp" type="number" min="0" max="60" value="1"></div><div data-role-extra="personnalite" hidden><label for="nu-cat">Catégorie</label><input id="nu-cat" name="categorie" maxlength="120" placeholder="Influenceur, artiste, sportif…"><label for="nu-bio">Bio / description</label><input id="nu-bio" name="bio" maxlength="500"></div><div><label for="nu-pw">Mot de passe provisoire</label><input id="nu-pw" name="password" type="password" minlength="10" required><span class="help">10 caractères minimum</span></div><div><button class="btn" type="submit">Créer le compte</button></div></form></div>
<div class="card" style="margin-top:16px"><h3>Lier un proche (parent/parrain) à un patient mineur</h3><p class="sub">Le parent et le parrain ont un rôle de soutien financier et de suivi pour les mineurs, avec accès limité. Le consentement doit être confirmé.</p><form data-f="link" class="form-grid"><div><label>Type de lien</label><select name="type"><option value="parent">Parent ou tuteur</option><option value="parrain">Parrain</option></select></div><div><label>Compte proche</label><select name="user_id" required>${proches.map(v=>`<option data-role="${v.role}" value="${v.id}" ${v.role!=='parent'?'hidden':''}>${esc(v.nom)} — ${ROLES[v.role]}</option>`).join('')||'<option value="">Aucun compte parent/parrain</option>'}</select></div><div><label>Patient</label><select name="patient_id" required>${P.map(v=>`<option value="${v.id}">${esc(v.nom)} (${esc(v.numero)}) · ${v.age} ans</option>`).join('')}</select></div><div class="check full"><label class="check-inline"><input type="checkbox" name="consentement" required><span>Lien vérifié et consentement recueilli</span></label></div><div><button class="btn" type="submit">Enregistrer le lien</button></div></form></div>
<div class="card" style="margin-top:16px"><h3>Liens actifs</h3>${tbl(['Proche','Patient','Type','Consentement',''],L.map(l=>[esc(l.responsable),`${esc(l.patient)} (${esc(l.numero)})`,ROLES[l.type]||esc(l.type),l.consentement?'Confirmé':'Non confirmé',`<button class="btn-danger btn-petit" data-a="unlink" data-user="${l.user_id}" data-patient="${l.patient_id}" data-type="${l.type}">Retirer</button>`]))}</div>
<div class="card" style="margin-top:16px"><h3>Comptes</h3>${tbl(['Nom','E-mail','Rôle','Statut',''],U.map(u=>[esc(u.nom),esc(u.email),ROLES[u.role]||esc(u.role),u.actif?'<span class="tag o">actif</span>':'<span class="tag w">désactivé</span>',`<button class="${u.actif?'btn-danger btn-petit' :'btn-secondaire btn-petit'}" data-a="toggle" data-id="${u.id}">${u.actif?'Désactiver' :'Réactiver'}</button>`]))}</div>`},
async aff(){const [P,Y]=await Promise.all([api('/admin/patients'),api('/psychologues')]);return `<h2>Affectations</h2><p class="sub">Attribuez les patients aux psychologues. Les personnalités sont associées aux programmes spéciaux depuis l’espace Programmes.</p><div class="card"><h3>Attribuer un psychologue</h3><form data-f="aff" class="form-grid"><div><label>Patient</label><select name="patient_id">${P.map(p=>`<option value="${p.id}">${esc(p.nom)} (${esc(p.numero)})</option>`).join('')}</select></div><div><label>Psychologue</label><select name="psy_id">${Y.map(y=>`<option value="${y.id}">${esc(y.nom)} · ${y.patients||0} patients</option>`).join('')}</select></div><div><button class="btn" type="submit">Attribuer</button></div></form></div><div class="card" style="margin-top:16px">${tbl(['N°','Patient','Âge','Psychologue actuel'],P.map(p=>[esc(p.numero),esc(p.nom),p.age,esc(p.psy||'—')]))}</div>`},
async tarifs(){const f=await api('/formules'),t=await api('/admin/tarif-seance');return `<h2>Tarifs</h2><p class="sub">L’administrateur peut réajuster le prix d’une séance à l’unité (par heure). Les abonnements restent comparables dans les espaces concernés.</p><div class="card"><h3>Prix d’une séance à l’unité</h3><form data-f="tarif" class="form-grid"><div><label>Tarif par heure (FCFA)</label><input type="number" name="tarif_seance" min="1000" step="500" value="${t.tarif_seance||f.tarif_seance||15000}" required></div><div><button class="btn" type="submit">Mettre à jour</button></div></form><p class="sub" style="margin-top:12px">Tarif actuel : <b>${F(t.tarif_seance||f.tarif_seance||15000)}</b> / heure (généralement 1 h, ajustable à l’achat).</p></div><div class="card" style="margin-top:16px"><h3>Abonnements</h3>${tbl(['Formule','Prix mensuel','Inclus'],Object.values(f.formules||{}).map(v=>[esc(v.label),F(v.prix),(v.inclus||[]).join(', ')]))}</div>`},
async audit(){const A=await api('/admin/audit');return `<h2>Journal d’audit</h2><p class="sub">Connexions, consultations de dossiers, accès refusés : traçabilité des actions sensibles.</p><div class="card">${tbl(['Date','Utilisateur','Action','Cible'],A.map(a=>[fd(a.ts),esc(a.utilisateur),esc(a.action),esc(a.cible)]))}</div>`},
async conf(){const R=[['Accès','Règles par rôle','Un soignant ne consulte que les patients qui lui sont attribués. Le suivi d’un mineur par son parent exige un lien et un consentement.'],['Comptes','Inscription professionnelle','Les comptes psychologue et médecin sont activés à l’inscription. L’accès aux dossiers reste limité aux patients attribués.'],['Sessions','Cookie de session','Cookie HttpOnly et SameSite ; l’attribut Secure est activé pour les connexions HTTPS.'],['Données','Stockage et sauvegardes','Le chiffrement de la base et des sauvegardes doit être configuré avant toute prise en charge réelle.'],['Services','Paiements et appels','Les informations de paiement et d’appel sont conservées dans l’espace concerné. Les prestataires doivent être configurés avant leur mise en service.']];
return `<h2>Sécurité & limites</h2><p class="sub">Informations sur la protection des comptes et des dossiers.</p><div class="note">Cette application n’est ni certifiée ISO/IEC 27001 ni prête pour des données réelles de santé. Avant sa mise en service, il faut faire auditer les accès, sécuriser l’hébergement et les sauvegardes, et faire valider les obligations juridiques et cliniques.</div><div class="card" style="margin-top:16px"><div class="k">Protection et services</div>${tbl(['Domaine','Mesure','Détail'],R.map(r=>[r[0],`<b>${r[1]}</b>`,r[2]]))}</div><div class="card" style="margin-top:16px"><div class="k">Étapes avant mise en service</div><ul class="c"><li>Faire valider les consentements, droits des proches, durées de conservation et obligations réglementaires au Sénégal.</li><li>Configurer un prestataire de paiement et un service de téléconsultation agréés.</li><li>Mettre en place des procédures de gestion des incidents, demandes de suppression et restauration des sauvegardes.</li></ul></div>`}};
/* ---------- actions ---------- */
const A={showSignup:()=>inscriptionView(),showPartners:()=>{partnerFilter='all';publicPartners()},backLogin:async()=>await loginView(),
filterPartner:t=>{partnerFilter=t.dataset.type;publicPartners()},
go:t=>{page=t.dataset.p;show()},logout:async()=>{await api('/logout',{});me=null;document.querySelectorAll('.toast').forEach(e=>e.remove());await loginView()},close:()=>$('#modal').classList.remove('on'),
fiche:t=>openFiche(t.dataset.id),pick:t=>{formule=t.dataset.k;show()},open:t=>{commOpen=+t.dataset.id;show()},
join:async t=>{await api(`/communautes/${t.dataset.id}/rejoindre`,{});commOpen=+t.dataset.id;show()},
inscrire:async t=>{await api(`/ateliers/${t.dataset.id}/inscrire`,{});toast('Inscription confirmée');show()},
toggle:async t=>{await api(`/admin/users/${t.dataset.id}/basculer`,{});show()},
cancelRdv:async t=>{if(!confirm('Annuler ce rendez-vous ?'))return;await api(`/rdv/${t.dataset.id}/annuler`,{});toast('Rendez-vous annulé');show()},
cancelSlot:async t=>{if(!confirm('Retirer ce créneau ?'))return;await api(`/psy/creneaux/${t.dataset.id}/annuler`,{});toast('Créneau retiré');show()},
unlink:async t=>{if(!confirm('Retirer ce lien et son accès au suivi ?'))return;await api(`/admin/liens/${t.dataset.user}/${t.dataset.patient}/${t.dataset.type}/retirer`,{});toast('Lien retiré');show()},
deleteCommunity:async t=>{if(!confirm('Supprimer cette communauté et ses échanges ?'))return;await api(`/communautes/${t.dataset.id}/supprimer`,{});commOpen=null;toast('Communauté supprimée');show()},
removePartner:async t=>{if(!confirm('Retirer ce partenaire de la page publique ?'))return;await api(`/admin/partenaires/${t.dataset.id}/retirer`,{});toast('Partenaire retiré');show()},
printReceipt:()=>{document.body.classList.add('printing-receipt');window.addEventListener('afterprint',()=>document.body.classList.remove('printing-receipt'),{once:true});window.print()},
seance:t=>{const call=t.dataset.mode==='appel'||t.dataset.mode==='appel_audio'||t.dataset.mode==='appel_video';const video=t.dataset.mode==='appel_video';openModal(`<h2>${call?(video?'Clôturer l’appel vidéo':'Clôturer l’appel vocal'):'Clôturer la séance'}</h2><p class="sub">Les informations et rapports restent réservés aux soignants.</p><form data-f="seance" data-id="${t.dataset.id}">${call?`<label>État de l’appel</label><select name="statut_appel"><option value="réalisé">Réalisé</option><option value="interrompu">Interrompu</option><option value="sans réponse">Sans réponse</option></select><label>Durée en minutes</label><input name="duree_min" type="number" min="0" max="240" value="30" required>`:''}<div data-session-fields><label>${call?'Rapport bref':'Compte rendu bref'}</label><textarea name="resume" rows="4" maxlength="2000" required></textarea><label>Évaluation psychologique de la séance</label><textarea name="evaluation" rows="3" maxlength="1500" required></textarea></div><br><button class="btn">Enregistrer</button> <button type="button" class="btn-secondaire" data-a="close">Annuler</button></form>`);},
startCall:t=>{const video=t.dataset.mode==='appel_video';const withName=t.dataset.with||'contact';const icon=video?'📹':'📞';openModal(`<div class="call-ui ${video?'video':''}"><div class="call-head"><span class="call-badge">${icon} ${video?'Appel vidéo':'Appel vocal'} sécurisé</span><h2>${esc(withName)}</h2><p class="sub">Session de consultation à distance · interface de démonstration</p></div><div class="call-stage">${video?'<div class="video-grid"><div class="video-tile main"><div class="avatar-lg">👤</div><span>'+esc(withName)+'</span></div><div class="video-tile self"><div class="avatar-lg">Vous</div></div></div>':'<div class="audio-stage"><div class="avatar-xl">👤</div><p>Connexion audio en cours avec <b>'+esc(withName)+'</b></p><div class="pulse"></div></div>'}</div><div class="call-controls"><button class="btn-secondaire btn-petit" type="button" data-a="callMute">Micro</button>${video?'<button class="btn-secondaire btn-petit" type="button" data-a="callCam">Caméra</button>':''}<button class="btn-danger" type="button" data-a="closeCall">Raccrocher</button></div><p class="note" style="margin-top:12px">Les échanges cliniques doivent être consignés par le psychologue à la clôture du rendez-vous.</p></div>`);},
callMute:()=>toast('Micro activé/désactivé'),
callCam:()=>toast('Caméra activée/désactivée'),
closeCall:()=>{A.close();toast('Appel terminé')}};
const S={login:async d=>{me=await api('/login',d);page=NAV[me.role][0][0];show()},
signup:async d=>{me=await api('/inscription',{role:d.role,nom:d.nom,email:d.email,password:d.password,date_naissance:d.date_naissance});page=NAV[me.role][0][0];show()},
rdv:async d=>{await api('/rdv',{slot_id:+d.slot_id,mode:d.mode,patient_id:d.patient_id?+d.patient_id:undefined});toast('Rendez-vous réservé');show()},
slot:async d=>{await api('/psy/creneaux',{date_heure:d.date_heure});toast('Créneau ajouté');show()},
link:async d=>{await api('/admin/liens',{user_id:+d.user_id,patient_id:+d.patient_id,type:d.type,consentement:d.consentement==='on'});toast('Lien enregistré');show()},
changer:async d=>{await api('/changer-psy',{psy_id:+d.psy_id,motif:d.motif});toast('Psychologue changé, historique conservé');show()},
abo:async(d,f)=>{const result=await api('/abonnement',{formule,methode:d.methode,patient_id:d.patient_id?+d.patient_id:undefined});await show();openModal(receiptHtml(result.recu))},
post:async d=>{await api(`/communautes/${commOpen}/posts`,{contenu:d.contenu});show()},
community:async d=>{await api('/communautes',{nom:d.nom,description:d.description});commOpen=null;toast('Communauté créée');show()},
partner:async(d,f)=>{const path=f.dataset.id?`/admin/partenaires/${f.dataset.id}`:'/admin/partenaires';await api(path,d);toast(f.dataset.id?'Partenaire mis à jour':'Partenaire ajouté');show()},
seance:async(d,f)=>{await api(`/rdv/${f.dataset.id}/seance`,{resume:d.resume,evaluation:d.evaluation,duree_min:d.duree_min?+d.duree_min:0,statut_appel:d.statut_appel});A.close();toast('Séance enregistrée');show()},
eval:async(d,f)=>{await api('/evaluations',{patient_id:+f.dataset.id,etat:d.etat,programme_id:d.programme_id?+d.programme_id:null});A.close();toast('Évaluation médicale enregistrée');show()},
newuser:async d=>{await api('/admin/users',d);toast('Compte créé');show()},
aff:async d=>{await api('/admin/affecter',{patient_id:+d.patient_id,psy_id:+d.psy_id});toast('Affectation enregistrée');show()},
tarif:async d=>{await api('/admin/tarif-seance',{tarif_seance:+d.tarif_seance});toast('Tarif mis à jour');show()},
progCreate:async d=>{await api('/admin/programmes',{nom:d.nom,description:d.description||'',personnalite_id:d.personnalite_id?+d.personnalite_id:null});toast('Programme créé');show()},
progLink:async(d,f)=>{await api(`/admin/programmes/${f.dataset.id}/personnalites`,{personnalite_id:+d.personnalite_id});toast('Personnalité associée');show()},
progActivite:async(d,f)=>{await api(`/admin/programmes/${f.dataset.id}/activites`,{titre:d.titre,type:d.type,description:d.description||'',date_heure:d.date_heure||''});toast('Activité ajoutée');show()},
seance_unitaire:async d=>{const result=await api('/abonnement',{type:'seance_unitaire',heures:+(d.heures||1),methode:d.methode,patient_id:d.patient_id?+d.patient_id:undefined});await show();openModal(receiptHtml(result.recu))}};
document.addEventListener('keydown',e=>{if(e.key==='Escape')A.close()});
document.addEventListener('change',async e=>{try{
if(e.target.name==='role'&&e.target.form&&e.target.form.dataset.f==='signup'){const birth=e.target.form.querySelector('[data-signup-fields="patient"]'),input=birth&&birth.querySelector('input');if(birth){birth.hidden=e.target.value!=='patient';if(input)input.required=e.target.value==='patient'}}
if(e.target.name==='role'&&e.target.form&&e.target.form.dataset.f==='newuser'){const role=e.target.value;for(const sec of e.target.form.querySelectorAll('[data-role-extra]')){const on=sec.dataset.roleExtra===role;sec.hidden=!on;for(const inp of sec.querySelectorAll('input')){if(inp.name==='date_naissance')inp.required=on;}}
}
if(e.target.name==='heures'&&e.target.form&&e.target.form.dataset.f==='seance_unitaire'){const h=Math.max(1,Math.min(20,+e.target.value||1));const tEl=e.target.form.querySelector('[data-unit-total]');if(tEl){const f=await api('/formules');tEl.textContent=F((f.tarif_seance||15000)*h)}}
if(e.target.name==='statut_appel'&&e.target.form){const missed=e.target.value==='sans réponse',fields=e.target.form.querySelector('[data-session-fields]'),duration=e.target.form.querySelector('[name=duree_min]');if(fields){fields.hidden=missed;for(const input of fields.querySelectorAll('textarea'))input.required=!missed}if(duration){duration.required=!missed;duration.value=missed?'0':'30'}}
if(e.target.name==='type'&&e.target.form&&e.target.form.dataset.f==='link'){const account=e.target.form.querySelector('[name=user_id]');for(const option of account.options)option.hidden=option.dataset.role!==e.target.value;const selected=account.selectedOptions[0];if(!selected||selected.hidden)account.value=[...account.options].find(option=>!option.hidden)?.value||''}
if(e.target.name==='patient_id'&&me.role==='parent'&&page==='rdv'){const pid=e.target.value,slots=await api(`/creneaux/${pid}`),suivi=await api('/suivi');const p=(suivi||[]).find(x=>String(x.id)===String(pid));const select=document.querySelector('[name=slot_id]'),button=document.querySelector('form[data-f=rdv] button');if(select)select.innerHTML=slotOptions(slots);if(button)button.disabled=!slots.length;const list=document.querySelector('#rdv-list');if(list&&p){const R=p.rdv||[];const callBtn=r=>r.statut==='prévu'&&(r.mode==='appel_audio'||r.mode==='appel_video'||r.mode==='appel')?`<span class="call-actions"><button class="btn btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_video" data-with="${esc(r.psy||'Psychologue')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/></svg> Appel vidéo</button><button class="btn-secondaire btn-petit call-btn" data-a="startCall" data-id="${r.id}" data-mode="appel_audio" data-with="${esc(r.psy||'Psychologue')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.63 2.63a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.45-1.2a2 2 0 0 1 2.11-.45c.85.3 1.73.51 2.63.63A2 2 0 0 1 22 16.92z"/></svg> Appel vocal</button></span>`:'';const rows=R.map(r=>[fd(r.date_heure),esc(r.psy||''),r.mode==='centre'?'Au centre':(r.mode==='appel_video'?'Visioconférence':'Appel vocal'),esc(r.lieu||''),`<span class="tag ${r.statut==='réalisé'?'o':''}">${esc(r.statut)}</span>`,(r.statut==='prévu'?`<button class="btn-danger btn-petit" data-a="cancelRdv" data-id="${r.id}">Annuler</button> `:'')+callBtn(r)]);list.innerHTML=`<h3>Mes rendez-vous</h3>${tbl(['Date','Psychologue','Mode','Lieu','Statut','Actions'],rows)}`}}
}catch(error){toast(error.message,1)}});
document.addEventListener('click',async e=>{if(e.target.id==='modal'){A.close();return}const t=e.target.closest('[data-a]');if(!t)return;try{await A[t.dataset.a](t)}catch(x){toast(x.message,1)}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-f]');if(!f)return;e.preventDefault();const btn=f.querySelector('button[type="submit"],button:not([type])');if(btn&&btn.disabled)return;const prev=btn?{h:btn.innerHTML,d:btn.disabled}:null;if(btn){btn.disabled=true;btn.classList.add('is-loading');btn.setAttribute('aria-disabled','true');btn.textContent='Envoi…'}try{await S[f.dataset.f](Object.fromEntries(new FormData(f)),f)}catch(x){toast(x.message,1)}finally{if(btn&&document.body.contains(btn)){btn.classList.remove('is-loading');btn.disabled=false;btn.removeAttribute('aria-disabled');if(prev)btn.innerHTML=prev.h}}});
boot();
